#include <bits/stdc++.h>
using namespace std;
typedef vector<int> Big;  // little-endian base-1e9 digits

Big add(const Big &a, const Big &b) {
    Big r;
    int carry = 0;
    for (size_t i = 0; i < max(a.size(), b.size()) || carry; i++) {
        long long s = carry + (i < a.size() ? a[i] : 0) + (i < b.size() ? b[i] : 0);
        r.push_back(s % 1000000000);
        carry = s / 1000000000;
    }
    return r;
}

int main() {
    string s;
    cin >> s;
    int n = s.size();
    // dp[i] = number of decodings of the first i digits.
    vector<Big> dp(n + 1, Big{0});
    dp[0] = Big{1};
    for (int i = 1; i <= n; i++) {
        if (s[i - 1] != '0') dp[i] = add(dp[i], dp[i - 1]);
        if (i > 1) {
            int two = (s[i - 2] - '0') * 10 + (s[i - 1] - '0');
            if (two >= 10 && two <= 26) dp[i] = add(dp[i], dp[i - 2]);
        }
    }
    const Big &r = dp[n];
    printf("%d", r.back());
    for (int i = (int)r.size() - 2; i >= 0; i--) printf("%09d", r[i]);
    printf("\n");
}

import java.io.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        int n = s.length();
        // dp[i] = number of decodings of the first i digits.
        BigInteger[] dp = new BigInteger[n + 1];
        dp[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            dp[i] = BigInteger.ZERO;
            if (s.charAt(i - 1) != '0') dp[i] = dp[i].add(dp[i - 1]);
            if (i > 1) {
                int two = Integer.parseInt(s.substring(i - 2, i));
                if (two >= 10 && two <= 26) dp[i] = dp[i].add(dp[i - 2]);
            }
        }
        System.out.println(dp[n]);
    }
}

